/* From Uiverse.io by sahilxkhadka - Tags: toggle, dynamic, mute */
.__UIV_SCOPE__ .switch {
  position: relative;
  width: 48px;
  height: 48px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: rgb(60,64,67);
  color: #fff;
  border-radius: 50%;
  cursor: pointer;
  transition: all .3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.__UIV_SCOPE__ .mic-on, .__UIV_SCOPE__ .mic-off {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .mic-on {
  z-index: 4;
}

.__UIV_SCOPE__ .mic-off {
  position: absolute;
  inset: 0;
  z-index: 5;
  opacity: 0;
}

.__UIV_SCOPE__ .switch:hover {
  background-color: rgba(60,64,67, 0.8);
}

.__UIV_SCOPE__ #checkbox {
  display: none;
}

.__UIV_SCOPE__ #checkbox:checked + .switch {
  background-color: red
}

.__UIV_SCOPE__ #checkbox:checked + .switch .mic-off {
  opacity: 1;
}

.__UIV_SCOPE__ #checkbox:active + .switch {
  scale: 1.2;
}
